mapper.select:
SELECT n.car_no, n.car_type,n.car_category car_cate, n.staff_name, n.staff_no, m.telephone phone, n.factory,
m.retention_num retention_nums, m.ctime noticeTime,m.inform_type notice_type, timestampdiff( HOUR, m.in_time, m.ctime ) stop_hours,
m.nums notice_nums, m.in_time, m.remind_type
FROM (SELECT t.car_no, t.in_time, t.inform_type, max( t.create_time ) ctime, count( t.in_time ) nums, t.telephone, t.remind_type, t.retention_num
FROM safety.safety_retention_inform_record t WHERE 1 = 1

    AND t.car_no like concat('%',#{param.carNo},'%')


    AND t.staff_no like concat('%',#{param.staffNo},'%')


    AND t.factory like concat('%',#{param.factory},'%')


    AND t.create_time >= #{param.noticeTimeStart}


    AND t.create_time <= #{param.noticeTimeEnd}


    AND t.inform_type = #{param.noticeType}

GROUP BY t.car_no, t.in_time, t.telephone, t.inform_type, t.remind_type, t.retention_num) m
LEFT JOIN safety.safety_car_in_factory n ON n.car_no = m.car_no WHERE 1 = 1

    AND n.park_status = #{param.carStatus}


    AND n.inform_status = #{param.noticeStatus}

ORDER BY ctime DESC LIMIT #{start}, #{end}

SELECT count(*) FROM (SELECT t.car_no, t.in_time, t.inform_type, max( t.create_time ) ctime, count( t.in_time ) nums, t.telephone, t.remind_type
FROM safety.safety_retention_inform_record t WHERE 1 = 1

    AND t.car_no = #{param.carNo}


    AND t.staff_no like concat('%',#{param.staffNo},'%')


    AND t.factory like concat('%',#{param.factory},'%')


    AND t.create_time >= #{param.noticeTimeStart}


    AND t.create_time <= #{param.noticeTimeEnd}


    AND t.inform_type = #{param.noticeType}

GROUP BY t.car_no, t.in_time, t.telephone, t.inform_type, t.remind_type) m
LEFT JOIN safety.safety_car_in_factory n ON n.car_no = m.car_no WHERE 1 = 1

    AND n.park_status = #{param.carStatus}


    AND n.inform_status = #{param.noticeStatus}
